// MineBench: steam choo-choo on a track through a meadow.
// Steam loco (bullet nose, cab, gold bands, dome, chimney, headlamp), tender, three passenger cars
// with glazed windows and lit interiors, a station with canopy and waiting passengers, a water tower,
// telegraph poles, trees, flowers, a hill and a smoke trail. Track runs along x at z=128.

// Every voxel goes into V first so later parts can overwrite or carve earlier ones.
// block() is called once per surviving voxel at the very end.
var V = {};
function put(x, y, z, t) {
  if (x < 0 || y < 0 || z < 0 || x > 255 || y > 255 || z > 255) return;
  V[x + ',' + y + ',' + z] = t;
}
function del(x, y, z) { delete V[x + ',' + y + ',' + z]; }
function fill(x1, y1, z1, x2, y2, z2, t) {
  for (var x = x1; x <= x2; x++)
    for (var y = y1; y <= y2; y++)
      for (var z = z1; z <= z2; z++) put(x, y, z, t);
}
function carve(x1, y1, z1, x2, y2, z2) {
  for (var x = x1; x <= x2; x++)
    for (var y = y1; y <= y2; y++)
      for (var z = z1; z <= z2; z++) del(x, y, z);
}
// deterministic 0..1 noise per voxel, so every run builds the same thing
function hash(x, y, z) {
  var h = Math.sin(x * 127.1 + y * 311.7 + z * 74.7) * 43758.5453;
  return h - Math.floor(h);
}

// ---------- terrain ----------
var GX1 = 4, GX2 = 251, GZ1 = 84, GZ2 = 172;
function groundH(x, z) {
  var a = (x - 60) / 38, b = (z - 172) / 16;     // big hill at the back edge
  var c = (x - 225) / 20, d = (z - 90) / 10;     // small knoll to the south-east
  return 2 + Math.round(14 * Math.exp(-(a * a + b * b)) + 8 * Math.exp(-(c * c + d * d)));
}
for (var gx = GX1; gx <= GX2; gx++) {
  for (var gz = GZ1; gz <= GZ2; gz++) {
    var h = groundH(gx, gz);
    fill(gx, 0, gz, gx, h - 2, gz, 'stone');
    put(gx, h - 1, gz, 'dirt');
    put(gx, h, gz, 'grass_block');
  }
}

// wildflowers in the meadow, kept clear of the track verge and the station
var FLOWERS = ['red_wool', 'yellow_wool', 'white_wool', 'orange_wool', 'purple_wool'];
for (var fx = GX1 + 2; fx <= GX2 - 2; fx++) {
  for (var fz = GZ1 + 2; fz <= GZ2 - 2; fz++) {
    if (fz > 110 && fz < 154) continue;
    if (hash(fx, 7, fz) > 0.985) {
      put(fx, groundH(fx, fz) + 1, fz, FLOWERS[Math.floor(hash(fz, 9, fx) * FLOWERS.length)]);
    }
  }
}

// ---------- track ----------
fill(6, 3, 119, 249, 3, 134, 'cobblestone');              // ballast
for (var tx = 6; tx <= 249; tx += 2) fill(tx, 4, 121, tx, 4, 134, 'oak_planks'); // sleepers
fill(6, 5, 124, 249, 5, 124, 'iron_block');                // rails
fill(6, 5, 132, 249, 5, 132, 'iron_block');

// telegraph poles with crossarms and two wires
for (var px = 14; px <= 222; px += 26) {
  fill(px, 3, 117, px, 13, 117, 'oak_log');
  fill(px, 12, 115, px, 12, 119, 'oak_planks');
  fill(px, 13, 115, px + 26, 13, 115, 'iron_block');
  fill(px, 13, 119, px + 26, 13, 119, 'iron_block');
}

// ---------- trees ----------
function leaf(x, y, z) {
  if (V[x + ',' + y + ',' + z] !== 'oak_log') put(x, y, z, 'oak_leaves');
}
function tree(x, z, trunkH, R, seed) {
  var base = groundH(x, z);
  for (var y = base + 1; y <= base + trunkH; y++) put(x, y, z, 'oak_log');
  var cy = base + trunkH + 1;
  for (var dx = -R - 1; dx <= R + 1; dx++)
    for (var dy = -R; dy <= R; dy++)
      for (var dz = -R - 1; dz <= R + 1; dz++) {
        var reach = R + (hash(x + dx, cy + dy, z + dz + seed) - 0.5) * 1.6;   // lumpy, not a clean ball
        if (dx * dx + dy * dy * 1.15 + dz * dz <= reach * reach) leaf(x + dx, cy + dy, z + dz);
      }
}
var TREES = [
  [24, 100, 6, 4], [40, 108, 5, 3], [18, 150, 6, 4], [52, 146, 7, 4], [72, 96, 5, 3],
  [96, 104, 6, 4], [120, 94, 5, 3], [30, 160, 6, 4], [88, 156, 5, 3], [108, 146, 6, 4],
  [236, 108, 6, 4], [228, 94, 5, 3], [160, 96, 6, 4], [186, 92, 5, 3], [136, 100, 6, 4],
  [12, 88, 5, 3], [202, 90, 6, 4]
];
for (var ti = 0; ti < TREES.length; ti++) {
  tree(TREES[ti][0], TREES[ti][1], TREES[ti][2], TREES[ti][3], ti * 17);
}

// ---------- station ----------
// platform: stone brick plinth, gold safety line on the track edge
fill(150, 3, 135, 200, 9, 140, 'stone_bricks');
fill(150, 10, 135, 200, 10, 140, 'stone_bricks');
fill(150, 10, 135, 200, 10, 135, 'gold_block');
// canopy on oak posts, glowstone lanterns underneath
var POSTS = [152, 168, 184, 198];
for (var pi = 0; pi < POSTS.length; pi++) {
  fill(POSTS[pi], 11, 136, POSTS[pi], 16, 136, 'oak_log');
  fill(POSTS[pi], 11, 139, POSTS[pi], 16, 139, 'oak_log');
}
fill(150, 17, 135, 200, 17, 141, 'oak_planks');
put(160, 16, 137, 'glowstone');
put(176, 16, 137, 'glowstone');
put(192, 16, 137, 'glowstone');
// two waiting passengers
function person(x, z, coat) {
  fill(x, 11, z, x, 12, z, 'black_wool');
  fill(x, 13, z, x, 14, z, coat);
  put(x, 15, z, 'orange_wool');
  put(x, 16, z, 'brown_wool');
}
person(162, 138, 'purple_wool');
person(179, 137, 'blue_wool');

// station house behind the platform: brick walls, gable roof, windows and a plank door
fill(156, 3, 143, 190, 16, 151, 'bricks');
for (var rz = 143; rz <= 151; rz++) {
  fill(155, 17, rz, 191, 17 + Math.min(rz - 143, 151 - rz), rz, 'gray_wool');
}
for (var wx = 156; wx <= 190; wx++) {
  for (var wy = 9; wy <= 13; wy++) {
    if ((wx - 156) % 5 === 2 || (wx - 156) % 5 === 3) put(wx, wy, 143, 'glass');
  }
}
fill(172, 3, 143, 173, 6, 143, 'oak_planks');

// water tower: four oak legs, plank tank with iron bands and a cone roof
for (var li = 0; li < 4; li++) {
  var lx = li < 2 ? 216 : 224, lz = li % 2 ? 150 : 158;
  fill(lx, 3, lz, lx, 14, lz, 'oak_log');
}
for (var ty = 15; ty <= 22; ty++)
  for (var tx2 = 214; tx2 <= 226; tx2++)
    for (var tz2 = 148; tz2 <= 160; tz2++) {
      var td = (tx2 - 220) * (tx2 - 220) + (tz2 - 154) * (tz2 - 154);
      if (td <= 16.5 && td > 6) put(tx2, ty, tz2, ty === 17 || ty === 21 ? 'iron_block' : 'oak_planks');
    }
for (var cy2 = 23; cy2 <= 26; cy2++) {
  var rr = 4.5 - (cy2 - 23) * 1.1;
  for (var cx2 = 214; cx2 <= 226; cx2++)
    for (var cz2 = 148; cz2 <= 160; cz2++)
      if ((cx2 - 220) * (cx2 - 220) + (cz2 - 154) * (cz2 - 154) <= rr * rr) put(cx2, cy2, cz2, 'gray_wool');
}

// ---------- wheels, shared by loco, tender and cars ----------
// A wheel is a disc in the XY plane: iron tyre, coloured face, gold hub, axle through it.
// Left pair sits at z 123-124, right pair at z 132-133, straddling the rails at z=124 and z=132.
function wheelPair(xc, yc, r, face) {
  for (var wx = xc - r; wx <= xc + r; wx++)
    for (var wy = yc - r; wy <= yc + r; wy++) {
      var d2 = (wx - xc) * (wx - xc) + (wy - yc) * (wy - yc);
      if (d2 > r * r + 0.5) continue;
      var t = d2 > (r - 1) * (r - 1) ? 'iron_block' : face;
      put(wx, wy, 123, t); put(wx, wy, 124, t);
      put(wx, wy, 132, t); put(wx, wy, 133, t);
    }
  fill(xc, yc, 124, xc, yc, 132, 'iron_block');
  put(xc, yc, 123, 'gold_block');
  put(xc, yc, 133, 'gold_block');
}

// ---------- locomotive (x 167..211, nose at 211) ----------
function boilerR(x) {                  // round boiler; bullet-shaped nose at the front
  if (x <= 204) return 5;
  var t = (x - 204) / 8;
  return 5 * Math.sqrt(Math.max(0, 1 - t * t));
}
// frame, drivers, connecting rod, pony truck
fill(167, 8, 126, 211, 10, 130, 'black_wool');
wheelPair(176, 10, 4, 'red_wool');
wheelPair(186, 10, 4, 'red_wool');
wheelPair(196, 10, 4, 'red_wool');
wheelPair(207, 8, 2, 'black_wool');
fill(176, 10, 122, 196, 10, 122, 'iron_block');      // connecting rod
// cowcatcher: iron bars sloping up toward the back
for (var fx2 = 206; fx2 <= 211; fx2++)
  for (var fy = 6; fy <= 8; fy++)
    if (fy - 6 <= (211 - fx2) / 3) fill(fx2, fy, 126, fx2, fy, 130, 'iron_block');
// boiler: black, gold bands (shell only), round nose
for (var bx = 181; bx <= 211; bx++) {
  var br = boilerR(bx);
  var band = (bx >= 190 && bx <= 191) || (bx >= 200 && bx <= 201);
  for (var by = 12; by <= 22; by++)
    for (var bz = 123; bz <= 133; bz++) {
      var bdy = by - 17, bdz = bz - 128;
      var bd2 = bdy * bdy + bdz * bdz;
      if (bd2 <= br * br + 0.5) {
        put(bx, by, bz, band && bd2 > (br - 1.5) * (br - 1.5) ? 'gold_block' : 'black_wool');
      }
    }
}
put(211, 17, 128, 'glowstone');                    // headlamp
// steam dome, bell, chimney with flared top and gold cap
for (var sx = 185; sx <= 189; sx++)
  for (var sz = 126; sz <= 130; sz++) {
    var sd = (sx - 187) * (sx - 187) + (sz - 128) * (sz - 128);
    if (sd <= 2.5) put(sx, 21, sz, 'gold_block');
    if (sd <= 1.5) put(sx, 22, sz, 'gold_block');
    if (sd <= 0.5) put(sx, 23, sz, 'gold_block');
  }
put(196, 23, 128, 'gold_block');
for (var kx = 200; kx <= 204; kx++)
  for (var kz = 126; kz <= 130; kz++) {
    var kd = (kx - 202) * (kx - 202) + (kz - 128) * (kz - 128);
    if (kd <= 2.5) for (var ky = 21; ky <= 28; ky++) put(kx, ky, kz, 'black_wool');
    if (kd <= 5) { put(kx, 29, kz, 'black_wool'); put(kx, 30, kz, 'black_wool'); }
    if (kd <= 5) put(kx, 31, kz, 'gold_block');
  }
// cab: red shell, hollow interior, glass in the sides and rear, gray roof, black floor
fill(167, 11, 125, 180, 24, 131, 'red_wool');
carve(168, 12, 126, 179, 23, 130);
fill(168, 11, 126, 179, 11, 130, 'black_wool');
for (var cwx = 168; cwx <= 179; cwx++)
  for (var cwy = 16; cwy <= 20; cwy++)
    if ((cwx - 167) % 4 !== 0) { put(cwx, cwy, 125, 'glass'); put(cwx, cwy, 131, 'glass'); }
fill(167, 16, 127, 167, 20, 129, 'glass');
fill(166, 25, 124, 181, 25, 132, 'gray_wool');

// ---------- tender (x 147..163) ----------
fill(147, 8, 126, 163, 10, 130, 'black_wool');
fill(147, 11, 125, 163, 19, 131, 'black_wool');
fill(147, 15, 125, 163, 15, 125, 'gold_block');     // gold stripes on both sides
fill(147, 15, 131, 163, 15, 131, 'gold_block');
fill(148, 20, 126, 162, 21, 130, 'black_wool');     // coal load
for (var cl = 148; cl <= 162; cl++)
  for (var cm = 126; cm <= 130; cm++)
    if (hash(cl, 21, cm) > 0.55) put(cl, 21, cm, 'cobblestone');
wheelPair(151, 9, 3, 'black_wool');
wheelPair(159, 9, 3, 'black_wool');

// ---------- passenger cars ----------
function car(x0) {
  var x1 = x0 + 31;
  fill(x0, 8, 126, x1, 10, 130, 'black_wool');          // underframe
  wheelPair(x0 + 6, 9, 3, 'black_wool');
  wheelPair(x1 - 6, 9, 3, 'black_wool');
  fill(x0, 11, 124, x1, 19, 132, 'red_wool');           // body
  for (var rx = x0; rx <= x1; rx++)                     // arched roof, round across the car
    for (var rz = 124; rz <= 132; rz++) {
      var rh = Math.round(4 * Math.sqrt(Math.max(0, 1 - Math.pow((rz - 128) / 4.6, 2))));
      fill(rx, 20, rz, rx, 19 + rh, rz, 'gray_wool');
    }
  carve(x0 + 1, 12, 125, x1 - 1, 19, 131);              // hollow interior
  fill(x0 + 1, 11, 125, x1 - 1, 11, 131, 'oak_planks'); // wooden floor
  for (var wx2 = x0 + 2; wx2 <= x1 - 2; wx2++) {        // glazed windows, 2 of every 4 blocks
    var k = (wx2 - x0) % 4;
    if (k === 1 || k === 2) {
      for (var wy2 = 14; wy2 <= 17; wy2++) { put(wx2, wy2, 124, 'glass'); put(wx2, wy2, 132, 'glass'); }
    }
  }
  fill(x0, 18, 124, x1, 18, 124, 'gold_block');         // gold window band
  fill(x0, 18, 132, x1, 18, 132, 'gold_block');
  fill(x0 + 14, 12, 124, x0 + 15, 15, 124, 'oak_planks'); // side doors
  fill(x0 + 14, 12, 132, x0 + 15, 15, 132, 'oak_planks');
  fill(x0 + 2, 12, 126, x1 - 2, 12, 126, 'oak_planks');   // benches, backs to the walls
  fill(x0 + 2, 13, 125, x1 - 2, 14, 125, 'oak_planks');
  fill(x0 + 2, 12, 130, x1 - 2, 12, 130, 'oak_planks');
  fill(x0 + 2, 13, 131, x1 - 2, 14, 131, 'oak_planks');
  var LAMPS = [x0 + 6, x0 + 16, x0 + 26];
  for (var lp = 0; lp < LAMPS.length; lp++) put(LAMPS[lp], 19, 128, 'glowstone');
}
car(113);
car(79);
car(45);
// couplers
fill(164, 9, 128, 166, 9, 128, 'iron_block');   // tender to loco
fill(145, 9, 128, 146, 9, 128, 'iron_block');   // tender to car 1
fill(111, 9, 128, 112, 9, 128, 'iron_block');
fill(77, 9, 128, 78, 9, 128, 'iron_block');

// ---------- smoke trail, shrinking puffs drifting back over the train ----------
function puff(cx, cy, cz, r) {
  var n = Math.ceil(r) + 1;
  for (var dx = -n; dx <= n; dx++)
    for (var dy = -n; dy <= n; dy++)
      for (var dz = -n; dz <= n; dz++) {
        var pr = r + (hash(cx + dx, cy + dy, cz + dz) - 0.5) * 1.2;
        if (dx * dx + dy * dy + dz * dz <= pr * pr) put(cx + dx, cy + dy, cz + dz, 'white_wool');
      }
}
for (var sp = 0; sp < 7; sp++) {
  puff(Math.round(202 - sp * 5 - sp * sp * 0.4), 34 + sp * 2, Math.round(128 + Math.sin(sp * 1.9) * 1.2), 3.6 - sp * 0.4);
}

// ---------- write everything out ----------
var count = 0;
for (var key in V) {
  var p = key.split(',');
  block(+p[0], +p[1], +p[2], V[key]);
  count++;
}
